import itertools,json
jobs='ABCDE'
slot={'A':[10,7,11,4,4],'B':[3,1,1,4,8],'C':[5,4,5,6,2],'D':[3,3,7,1,11],'E':[10,9,10,1,9]}
trans=dict(zip(jobs,[[0,3,3,5,0],[5,0,3,2,0],[5,3,0,2,1],[4,2,4,0,5],[1,5,4,1,0]]))
def nominal(p):
 return sum(slot[j][i] for i,j in enumerate(p))+sum(trans[a][jobs.index(b)] for a,b in zip(p,p[1:]))
def legal(p,s):
 if p.index('A')>p.index('D'):return False
 return {'rain':p[4]!='C' and p[0]!='A','road':p[0]!='B' and p[1]!='C','lift':p[4] not in 'DB'}[s]
def penalty(p,s):
 return {'rain':8*max(0,p.index('E')),'road':5*max(0,p.index('D')-2),'lift':5*max(0,p.index('E')-1)}[s]
results=[]
for p in itertools.permutations(jobs):
 if p.index('A')>p.index('D'):continue
 neighbors=[(p,0)]
 for i,j in itertools.combinations(range(5),2):
  q=list(p);q[i],q[j]=q[j],q[i];neighbors.append((tuple(q),1))
 repairs={};costs={}
 for s in ['rain','road','lift']:
  options=[(nominal(q)+penalty(q,s)+ex,''.join(q)) for q,ex in neighbors if legal(q,s)]
  if not options:break
  costs[s],repairs[s]=min(options)
 else:
  results.append({'roster':''.join(p),'score':nominal(p)+max(costs.values()),'repairs':repairs,'repair_costs':costs})
results.sort(key=lambda x:(x['score'],x['roster']))
best=results[0].copy();best['feasible_count']=len(results);best['next_score']=min(r['score'] for r in results if r['score']>best['score'])
print(json.dumps(best))
print('published nominal',nominal(tuple(best['roster'])))
print('optima',[(r['roster'],r['score']) for r in results if r['score']==best['score']])

